WITH order_items_by_product AS (SELECT product_id, COUNT(*) AS row_count, COUNT(*) AS order_item_count FROM order_items GROUP BY product_id) SELECT products.id, products.category, order_items_by_product.row_count, order_items_by_product.order_item_count FROM products LEFT OUTER JOIN order_items_by_product ON products.id = order_items_by_product.product_id WHERE order_items_by_product.order_item_count >= 4 ORDER BY row_count DESC
